(501993, 49252, 10170, '<td valign="top">Very well taken indeed.  I love the angle and lighting, and not having too narrow a DOF was a great choice here.</td>', 'Very well taken indeed.  I love the angle and lighting, and not having too narrow a DOF was a great choice here.', '2003-12-03 03:56:47.000000', NULL, 1),
(501994, 49249, 7263, '<td valign="top">maybe a privatisation title would be more apt? Is this JL?</td>', 'maybe a privatisation title would be more apt? Is this JL?', '2003-12-03 03:56:50.000000', NULL, 1),
