(502127, 49312, 11096, '<td valign="top">I love the soft focus.  Not sure how it fits the challenge but will give you the benefit of the doubt.</td>', 'I love the soft focus.  Not sure how it fits the challenge but will give you the benefit of the doubt.', '2003-12-03 08:28:42.000000', NULL, 1),
(502128, 48912, 12733, '<td valign="top">Shouldn''t this have been entered in the "Propaganda" challenge? Nice shot, and it makes a good point.</td>', 'Shouldn''t this have been entered in the "Propaganda" challenge? Nice shot, and it makes a good point.', '2003-12-03 08:29:54.000000', NULL, 1),
(502129, 49269, 11096, '<td valign="top">A little too much glare on the left side but good idea and composition</td>', 'A little too much glare on the left side but good idea and composition', '2003-12-03 08:29:58.000000', NULL, 1),
(502130, 48872, 1204, '<td valign="top">I''m not sure I''d have made the connection without the title - but that actually goes for most of the entries for this challenge.  This is also one of quite many entries that indicates that people have learned from the soft-focus challenge...  On the photo itself - this line of shadow across the back bothers me a bit, a small light or a reflector on the right side of the camera might have softened this effect.  8.</td>', 'I''m not sure I''d have made the connection without the title - but that actually goes for most of the entries for this challenge.  This is also one of quite many entries that indicates that people have learned from the soft-focus challenge...  On the photo itself - this line of shadow across the back bothers me a bit, a small light or a reflector on the right side of the camera might have softened this effect.  8.', '2003-12-03 08:30:34.000000', NULL, 1),
(502131, 49360, 12061, '<td valign="top">great colors and composition, an excellent subject for this challenge. Focus is very crisp.<br/>would like to see the sharp white edges toned down a bit</td>', 'great colors and composition, an excellent subject for this challenge. Focus is very crisp.would like to see the sharp white edges toned down a bit', '2003-12-03 08:31:15.000000', NULL, 1),
