(503176, 49395, 9763, '<td valign="top">Sad that your shadow is in this one.  It could have been great.  I like the natural looking lighting.</td>', 'Sad that your shadow is in this one.  It could have been great.  I like the natural looking lighting.', '2003-12-04 00:42:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(503181, 49283, 5822, '<td valign="top">Wonderfully rich, bright and saturated colors!!! What I"m getting from this picture is indecison on what to buy from the numerous choices presented by the street vendors.  I love the way you''ve managed to capture the woman in the middle of the frame in motion and appearing to turn to and fro undecided about what to buy countered by the three other women who are still and appearing relatively in focus...This is a wonderful effect!  Adding to the effect is the verdant green bus in motion in the background which gives the whole scene the feeling of the hustle and bustle of city life. The only question I have about this image is the use of a very thick border that has a grey outer edge.  Not too crazy about it, but I do feel that the heavy black border does make the bright colors stand out even more.  I really love this picture and hope it does well. Good luck.</td>', 'Wonderfully rich, bright and saturated colors!!! What I"m getting from this picture is indecison on what to buy from the numerous choices presented by the street vendors.  I love the way you''ve managed to capture the woman in the middle of the frame in motion and appearing to turn to and fro undecided about what to buy countered by the three other women who are still and appearing relatively in focus...This is a wonderful effect!  Adding to the effect is the verdant green bus in motion in the background which gives the whole scene the feeling of the hustle and bustle of city life. The only question I have about this image is the use of a very thick border that has a grey outer edge.  Not too crazy about it, but I do feel that the heavy black border does make the bright colors stand out even more.  I really love this picture and hope it does well. Good luck.', '2003-12-04 01:03:33.000000', NULL, 1),
(503182, 49003, 11078, '<td valign="top">this would have been better in shadows I dont see the connection with money</td>', 'this would have been better in shadows I dont see the connection with money', '2003-12-04 01:08:11.000000', NULL, 1),
(503193, 49295, 4967, '<td valign="top">instead of just scattering them randomly, it might have been kind of cool to form a dollar sign with the gems.  Just an idea though... I like the plain black background.</td>', 'instead of just scattering them randomly, it might have been kind of cool to form a dollar sign with the gems.  Just an idea though... I like the plain black background.', '2003-12-04 02:10:10.000000', NULL, 1),
(503195, 49317, 4967, '<td valign="top">It almost looks like you took this picture with the 10D thats sitting there... I''m wondering if you too the reflection a mirror and then switched it back to normal in photo shop?  I''m guessing this because of the kind of the flare at the top, although I do seem to see some people reflected in the lens on the camera, so I''m not sure.  cute idea though... even if you did choose canon ;-)<br/></td>', 'It almost looks like you took this picture with the 10D thats sitting there... I''m wondering if you too the reflection a mirror and then switched it back to normal in photo shop?  I''m guessing this because of the kind of the flare at the top, although I do seem to see some people reflected in the lens on the camera, so I''m not sure.  cute idea though... even if you did choose canon ;-)', '2003-12-04 02:16:35.000000', NULL, 1),
(503196, 49365, 12896, '<td valign="top">true..</td>', 'true..', '2003-12-04 02:20:04.000000', NULL, 1),
(503197, 49343, 14522, '<td valign="top">Nice idea but I think let down by the actaul subject itself. The buildign is not particulary attractive and the view point selected is not flattering either. The reflections in the windows are disturbing - too bright at the top and the lower ons has telephone lines. The sign, whilst there, is difficult to read - and I think it is an important part of the whole - and could stand a bit more saturation.<br/>I get a subtle bit of humour as I imagine New York to be concrete, steel and skyscrapers but here you have a small stone building - more of a shrine.</td>', 'Nice idea but I think let down by the actaul subject itself. The buildign is not particulary attractive and the view point selected is not flattering either. The reflections in the windows are disturbing - too bright at the top and the lower ons has telephone lines. The sign, whilst there, is difficult to read - and I think it is an important part of the whole - and could stand a bit more saturation.I get a subtle bit of humour as I imagine New York to be concrete, steel and skyscrapers but here you have a small stone building - more of a shrine.', '2003-12-04 02:29:05.000000', NULL, 1),
(503198, 49356, 14522, '<td valign="top">Lovely - but I''d want a 1Ds. There are a few white spots that ought to be cleaned up.</td>', 'Lovely - but I''d want a 1Ds. There are a few white spots that ought to be cleaned up.', '2003-12-04 02:30:34.000000', NULL, 1),
(503199, 49362, 14522, '<td valign="top">A difficult picture to have taken - I didn''t realise that casinos allowed photographs. Basically you have an exposure problem. It is too dark and the areas that are lit are soft - hand held shot at too long an exposure? The picture is really the right half of the image.</td>', 'A difficult picture to have taken - I didn''t realise that casinos allowed photographs. Basically you have an exposure problem. It is too dark and the areas that are lit are soft - hand held shot at too long an exposure? The picture is really the right half of the image.', '2003-12-04 02:33:12.000000', NULL, 1),
(503200, 48896, 14522, '<td valign="top">I don''t associate motorbikes with money. Yes, I realise that the Sunday rider is ususally monied but I have enough of an image of Hell''s Angels types. Image is nice albeit a little soft.</td>', 'I don''t associate motorbikes with money. Yes, I realise that the Sunday rider is ususally monied but I have enough of an image of Hell''s Angels types. Image is nice albeit a little soft.', '2003-12-04 02:35:58.000000', NULL, 1),
