(505910, 49298, 8891, '<td valign="top">nice stash, lighting could have been better, comp is ok.</td>', 'nice stash, lighting could have been better, comp is ok.', '2003-12-07 14:26:30.000000', NULL, 1),
(505912, 49419, 8891, '<td valign="top">nice exposure on the bank, very little blowout at all.  The horse shot and its inclusion in the picture bothers me from a challenge point of view: but I''ll take for granted that the shot is yours and, if it is, it is a fine shot as well.  Don''t know that you needed to necessarily show the dream...the bank it self would have been just fine for me....the BG is superfluous IMHO.</td>', 'nice exposure on the bank, very little blowout at all.  The horse shot and its inclusion in the picture bothers me from a challenge point of view: but I''ll take for granted that the shot is yours and, if it is, it is a fine shot as well.  Don''t know that you needed to necessarily show the dream...the bank it self would have been just fine for me....the BG is superfluous IMHO.', '2003-12-07 14:29:21.000000', NULL, 1),
