(506329, 49151, 14522, '<td valign="top">There is a loss of detail in the white at the top of the boot.</td>', 'There is a loss of detail in the white at the top of the boot.', '2003-12-08 01:38:58.000000', NULL, 1),
(506332, 49350, 14522, '<td valign="top">Preety good composition. Strong diagonal lead in. Was this shot under a flourescent light? Did you want this colour or wasn''t the white balance set.</td>', 'Preety good composition. Strong diagonal lead in. Was this shot under a flourescent light? Did you want this colour or wasn''t the white balance set.', '2003-12-08 01:40:40.000000', NULL, 1),
(506335, 49417, 14522, '<td valign="top">Lighting is uneven over the image. The top appears brighter than the bottom.</td>', 'Lighting is uneven over the image. The top appears brighter than the bottom.', '2003-12-08 01:42:25.000000', NULL, 1),
