(506338, 49409, 14522, '<td valign="top">The composition causes the eye to move around the iamge and not concentrate on the lens.</td>', 'The composition causes the eye to move around the iamge and not concentrate on the lens.', '2003-12-08 01:45:07.000000', NULL, 1),
