(506344, 49122, 14522, '<td valign="top">Enough detail to convey the point. Perhaps a bit too bright on the sides.</td>', 'Enough detail to convey the point. Perhaps a bit too bright on the sides.', '2003-12-08 01:52:35.000000', NULL, 1),
