(506402, 49403, 14522, '<td valign="top">DOF an issue</td>', 'DOF an issue', '2003-12-08 02:30:29.000000', NULL, 1),
(506403, 49053, 14522, '<td valign="top">Almost.</td>', 'Almost.', '2003-12-08 02:31:51.000000', NULL, 1),
