(506406, 49034, 14522, '<td valign="top">Focus appears soft</td>', 'Focus appears soft', '2003-12-08 02:32:55.000000', NULL, 1),
(506407, 49245, 14522, '<td valign="top">Pretty much a true sentiment. The light source has created a hot spot. I would say flash but that is too close to flush and the cards may cause a blockage.</td>', 'Pretty much a true sentiment. The light source has created a hot spot. I would say flash but that is too close to flush and the cards may cause a blockage.', '2003-12-08 02:35:03.000000', NULL, 1),
(506408, 49354, 14522, '<td valign="top">And to think that that pig cost money.</td>', 'And to think that that pig cost money.', '2003-12-08 02:36:17.000000', NULL, 1),
(506409, 49380, 14522, '<td valign="top">Underexposed and soft</td>', 'Underexposed and soft', '2003-12-08 02:37:22.000000', NULL, 1),
(506411, 49397, 14522, '<td valign="top">Well exposed</td>', 'Well exposed', '2003-12-08 02:38:12.000000', NULL, 1),
(506412, 49423, 14522, '<td valign="top">The bright spot in the image is distracting</td>', 'The bright spot in the image is distracting', '2003-12-08 02:39:44.000000', NULL, 1),
(506413, 49371, 14522, '<td valign="top">Cats cheat</td>', 'Cats cheat', '2003-12-08 02:40:11.000000', NULL, 1),
(506430, 48889, 14522, '<td valign="top">Perhaps a read of the rules would help</td>', 'Perhaps a read of the rules would help', '2003-12-08 03:21:54.000000', NULL, 1),
(506443, 49309, 12160, '<td valign="top">Does this suggest that the other green paper comes from plant/tree. Hard for me to see money in the photo. Maybe you can help me figure it out. I''ll start with a 5.</td>', 'Does this suggest that the other green paper comes from plant/tree. Hard for me to see money in the photo. Maybe you can help me figure it out. I''ll start with a 5.', '2003-12-08 04:04:12.000000', NULL, 1),
(506451, 49210, 9668, '<td valign="top">Excellent Theme, great picture</td>', 'Excellent Theme, great picture', '2003-12-08 04:24:15.000000', NULL, 1),
(506458, 49360, 9668, '<td valign="top">I really like this shot, it does have the "resemblence of real currency" but it isn''t "real currency." I like the orange frame around it, but the background is a little distracting. 9</td>', 'I really like this shot, it does have the "resemblence of real currency" but it isn''t "real currency." I like the orange frame around it, but the background is a little distracting. 9', '2003-12-08 04:34:45.000000', NULL, 1),
(506472, 49212, 9668, '<td valign="top">It does have a "look like real currency," but I like the shot enough to not count that in. This image has a very cool effect. The hairs? under some of the water drops are a little distracting.</td>', 'It does have a "look like real currency," but I like the shot enough to not count that in. This image has a very cool effect. The hairs? under some of the water drops are a little distracting.', '2003-12-08 04:43:44.000000', NULL, 1),
(506478, 49010, 10084, '<td valign="top">Need to up the contrast. The shot looks a bit flat. <br/> <br/>Otherwise the scene is composition is very nice. I like how your eyes are lead from the foreground toward the sunset by the road and the white fence. The angle of the clouds also lead your eyes toward the sun.</td>', 'Need to up the contrast. The shot looks a bit flat.  Otherwise the scene is composition is very nice. I like how your eyes are lead from the foreground toward the sunset by the road and the white fence. The angle of the clouds also lead your eyes toward the sun.', '2003-12-08 04:48:29.000000', NULL, 1),
(506506, 49426, 13941, '<td valign="top">Great shot! The only correectable thing I can find here is the composition is not symetric. I would have made the cards symetric but who knows - maybe it would just spoil the picture. (9)</td>', 'Great shot! The only correectable thing I can find here is the composition is not symetric. I would have made the cards symetric but who knows - maybe it would just spoil the picture. (9)', '2003-12-08 06:09:58.000000', NULL, 1),
(506600, 49414, 14754, '<td valign="top">beautiful background and coloration</td>', 'beautiful background and coloration', '2003-12-08 08:44:33.000000', NULL, 1),
