(508492, 48998, 12253, '<td valign="top">Good colors and fits theme well.  I think I might have considered cropping the left a bit.</td>', 'Good colors and fits theme well.  I think I might have considered cropping the left a bit.', '2003-12-09 23:53:49.000000', NULL, 1),
(508494, 49388, 5822, '<td valign="top">This shot is so expressive and fits the challenge perfectly !  I love the predominantly low-key tones and your cropping.  The lack of identity of this person was very wise as it shows poverty more of a societal problem than just an individual''s plight.  The clutching hand and dirty cup add to the emotion and I like your point-of-view, as well. The lighting way down at the bottom gives it a glimmer of hope, though. Very well done!</td>', 'This shot is so expressive and fits the challenge perfectly !  I love the predominantly low-key tones and your cropping.  The lack of identity of this person was very wise as it shows poverty more of a societal problem than just an individual''s plight.  The clutching hand and dirty cup add to the emotion and I like your point-of-view, as well. The lighting way down at the bottom gives it a glimmer of hope, though. Very well done!', '2003-12-09 23:57:22.000000', NULL, 1),
(508501, 49260, 10084, '<td valign="top">Great closeup of the jeans. Beautiful capture of the flame. Congratulations on the ribbon. Gave you a "10"</td>', 'Great closeup of the jeans. Beautiful capture of the flame. Congratulations on the ribbon. Gave you a "10"', '2003-12-10 00:06:01.000000', NULL, 0),
